//! ↩️ reorder-nodes leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfNode;
use crate::artifacts::gltf::schema::mutations::reorder_nodes::mutation::{validate, GltfReorderNodesPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{nodes_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-nodes.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderNodesInverseOperation { Insert { position: usize, item: GltfNode }, Delete { index: usize, removed: GltfNode }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderNodesInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderNodesPayload, pub operation: GltfReorderNodesInverseOperation }
fn operation(payload: &GltfReorderNodesPayload, base: &GltfSnapshot) -> GltfReorderNodesInverseOperation { GltfReorderNodesInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
fn touched_paths(payload: &GltfReorderNodesPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/nodes/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_inverse(inverse: &GltfReorderNodesInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfReorderNodesInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderNodesInverseOperation::Insert { position, .. } if *position > after.document.nodes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/nodes", "position must be within the collection")), GltfReorderNodesInverseOperation::Delete { index, .. } if *index >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "index must address an item")), GltfReorderNodesInverseOperation::Move { index, position } if *index >= after.document.nodes.len() || *position >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "indices must address items")), GltfReorderNodesInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.nodes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.nodes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/nodes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderNodesInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Nodes, &Change::Insert(*position))?; next.document.nodes.insert(*position, item.clone());  }, GltfReorderNodesInverseOperation::Delete { index, .. } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, None, None)?;  }, GltfReorderNodesInverseOperation::Move { index, position } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, Some(*position), None)?;  }, GltfReorderNodesInverseOperation::Reorder { order } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfReorderNodesInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfReorderNodesPayload, base: &GltfSnapshot) -> Result<GltfReorderNodesInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderNodesInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
